// Run via: pnpm exec tsx --env-file=.env scripts/cleanup-tests.ts

import { db } from "../src/server/db";
import { DeleteObjectCommand } from "@aws-sdk/client-s3";
import { s3Client } from "../src/server/s3"; // Adjust path to your s3Client if needed

async function main() {
  console.log("Starting cleanup of test data...");

  // 1. Find all images generated by the test scripts
  const testImages = await db.busImage.findMany({
    where: {
      cameraId: {
        in: ["Test-Upload-Cam", "Test-Inference-Cam"],
      },
    },
    include: { inferences: true }, // Include so we can see what we're deleting
  });

  if (testImages.length === 0) {
    console.log("No test images found in the database. You're clean!");
    return;
  }

  console.log(`Found ${testImages.length} test images to delete.`);

  // 2. Loop through and delete from Cloudflare R2 first
  for (const image of testImages) {
    // Extract the unique file key from the end of your public URL
    // e.g., https://your-r2.com/inference-uploads/1234.jpg -> inference-uploads/1234.jpg
    const urlParts = image.imageUrl.split("/");
    const folder = urlParts[urlParts.length - 2];
    const filename = urlParts[urlParts.length - 1];
    const objectKey = `${folder}/${filename}`;

    try {
      await s3Client.send(
        new DeleteObjectCommand({
          Bucket: process.env.R2_BUCKET_NAME,
          Key: objectKey,
        })
      );
      console.log(`Deleted from R2: ${objectKey}`);
    } catch (error) {
      console.error(`Failed to delete ${objectKey} from R2:`, error);
    }
  }

  // 3. Delete from Neon Database
  // Because your schema has `onDelete: Cascade` on the InferenceLog relation,
  // deleting the BusImage will automatically delete the linked InferenceLogs!
  const deletedDbRecords = await db.busImage.deleteMany({
    where: {
      cameraId: {
        in: ["Test-Upload-Cam", "Test-Inference-Cam"],
      },
    },
  });

  console.log(`Successfully deleted ${deletedDbRecords.count} records from the Neon database.`);
  console.log("Cleanup complete!");
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });